const ico = (n, s) => '<svg class="ico" width="' + (s || 20) + '" height="' + (s || 20) + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (ICONS[n] || '') + '</svg>';
function hydrateIcons(root){ $$('i[data-i]', root).forEach(el => { el.outerHTML = ico(el.dataset.i, +el.dataset.s || 20); }); }

/* ---------- ظرفیت ---------- */
function capHTML(key){
