  if(!c) return '<span class="pill">ظرفیت محدود</span>';
  const left = c.total - c.filled;
  if(left <= 0) return '<span class="pill pill-danger">تکمیل ظرفیت</span>';
  const pct = Math.round(c.filled / c.total * 100);
  return '<span class="pill ' + (left <= 3 ? 'pill-warn' : 'pill-ok') + '">' + (left <= 3 ? 'فقط ' : '') + fa(left) + ' جای خالی</span><span class="meter" aria-hidden="true"><i style="width:' + pct + '%"></i></span>';
}
const isFull = key => { const c = CONFIG.capacity[key]; return !!c && c.filled >= c.total; };

/* ---------- سازنده فرم ---------- */
function makeForm(host, def){
  const fid = n => def.id + '-' + n;
  const optsOf = (f, v) => typeof f.options === 'function' ? f.options(v) : f.options;
  const fieldHTML = f => {
    const i = fid(f.name);
    const req = f.required ? ' <span class="req" aria-hidden="true">*</span>' : '';
    if(f.type === 'check') return '<div class="field wide"><label class="check" for="' + i + '"><input type="checkbox" id="' + i + '" name="' + f.name + '"><span>' + f.label + '</span></label><p class="err" id="' + i + '-err" hidden></p></div>';
    let ctl;
    if(f.type === 'select') ctl = '<select id="' + i + '" name="' + f.name + '"></select>';
    else if(f.type === 'textarea') ctl = '<textarea id="' + i + '" name="' + f.name + '" rows="' + (f.rows || 3) + '" placeholder="' + (f.ph || '') + '"></textarea>';
    else ctl = '<input id="' + i + '" name="' + f.name + '" type="text"' + (f.mode ? ' inputmode="' + f.mode + '"' : '') + (f.ltr ? ' dir="ltr" class="ltr"' : '') + ' placeholder="' + (f.ph || '') + '" autocomplete="' + (f.ac || 'off') + '">';
    return '<div class="field' + (f.wide ? ' wide' : '') + '"><label for="' + i + '">' + f.label + req + '</label>' + ctl + (f.hint ? '<p class="hint">' + f.hint + '</p>' : '') + '<p class="err" id="' + i + '-err" hidden></p></div>';
  };
  host.innerHTML = '<form class="form" novalidate>' + def.fields.map(fieldHTML).join('') + '<div class="actions"><button class="btn btn-primary" type="submit">' + def.submit + '</button></div></form><div class="done" hidden></div>';
  const form = $('form', host), done = $('.done', host);
  const el = n => $('#' + fid(n), host);
  const vals = () => { const o = {}; def.fields.forEach(f => { const e = el(f.name); o[f.name] = f.type === 'check' ? e.checked : e.value.trim(); }); return o; };
  const fillSelect = (f, v) => {
    const e = el(f.name), cur = e.value, list = optsOf(f, v);
    e.innerHTML = '<option value="">' + (f.ph || 'انتخاب کنید') + '</option>' + list.map(o => '<option value="' + o[0] + '"' + (o[2] ? ' disabled' : '') + '>' + o[1] + '</option>').join('');
    if(list.some(o => o[0] === cur && !o[2])) e.value = cur;
  };
  def.fields.filter(f => f.type === 'select').forEach(f => fillSelect(f, {}));
  const refresh = () => { const v = vals(); def.fields.filter(f => f.type === 'select' && typeof f.options === 'function').forEach(f => fillSelect(f, v)); };
  form.addEventListener('change', e => { refresh(); if(e.target.getAttribute('aria-invalid')) clearErr(e.target.name); });
  form.addEventListener('input', e => { if(e.target.getAttribute('aria-invalid')) clearErr(e.target.name); });

  function clearErr(n){ const e = el(n), p = $('#' + fid(n) + '-err', host); e.removeAttribute('aria-invalid'); p.hidden = true; }
  function validate(){
    const v = vals(), errs = {};
    def.fields.forEach(f => {
      const x = v[f.name];
      if(f.type === 'check'){ if(f.required && !x) errs[f.name] = 'برای ادامه باید این مورد را تأیید کنید.'; return; }
      if(f.required && !x){ errs[f.name] = 'این بخش را تکمیل کنید.'; return; }
      if(!x) return;
      if(f.kind === 'phone' && !/^09\d{9}$/.test(en(x).replace(/[\s-]/g, ''))) errs[f.name] = 'شماره موبایل را به‌صورت ۰۹۱۲۳۴۵۶۷۸۹ وارد کنید.';
      if(f.kind === 'num'){ const n = Number(en(x)); if(!isFinite(n) || n < f.min || n > f.max) errs[f.name] = 'عددی بین ' + fa(f.min) + ' تا ' + fa(f.max) + ' وارد کنید.'; }
    });
    if(def.validate){ const extra = def.validate(v) || {}; Object.keys(extra).forEach(k => { if(!errs[k]) errs[k] = extra[k]; }); }
    return errs;
  }
  function summary(){
    const v = vals(), lines = [def.title, ''];
    def.fields.forEach(f => {
      if(f.type === 'check' || !v[f.name]) return;
      let x = v[f.name];
      if(f.type === 'select'){ const o = optsOf(f, v).find(o => o[0] === x); x = o ? o[1] : x; }
      lines.push(f.label + ': ' + x);
    });
    return lines.join('\n');
  }
  function showDone(){
    const text = summary();
    const wa = CONFIG.whatsapp ? 'https://wa.me/' + CONFIG.whatsapp + '?text=' + encodeURIComponent(text) : '';
    done.innerHTML =
      '<div class="done-head"><span class="bub">' + ico('check', 26) + '</span><div><h3>اطلاعات شما آماده ارسال است</h3><p class="muted">' + def.doneNote + '</p></div></div>' +
      '<pre class="msg" tabindex="0"></pre>' +
      (wa ? '' : '<p class="note">ارسال خودکار هنوز فعال نشده است. متن بالا را کپی کنید و برای مربی بفرستید.</p>') +
      '<div class="actions" style="padding:0">' +
        (wa ? '<a class="btn btn-primary" target="_blank" rel="noopener" href="' + wa + '">' + ico('whatsapp') + 'ارسال از طریق واتساپ</a>' : '') +
        '<button type="button" class="btn ' + (wa ? 'btn-ghost' : 'btn-primary') + '" data-act="copy">' + ico('copy') + '<span>کپی متن</span></button>' +
        '<button type="button" class="btn btn-ghost" data-act="edit">' + ico('edit') + 'ویرایش اطلاعات</button>' +
      '</div>';
    $('.msg', done).textContent = text;
    form.hidden = true; done.hidden = false;
    done.scrollIntoView({block: 'nearest', behavior: reduce ? 'auto' : 'smooth'});
  }
  form.addEventListener('submit', async e => {
    e.preventDefault();
    const errs = validate();
    def.fields.forEach(f => { clearErr(f.name); });
    const keys = Object.keys(errs);
    if(keys.length){
      keys.forEach(k => { const p = $('#' + fid(k) + '-err', host); p.textContent = errs[k]; p.hidden = false; el(k).setAttribute('aria-invalid', 'true'); });
      el(keys[0]).focus();
      return;
    }
    try {
      const response = await fetch('/forms', {
        method: 'POST',
        headers: {'Content-Type': 'application/json', 'Accept': 'application/json', 'X-CSRF-TOKEN': document.querySelector('meta[name=csrf-token]').content},
        body: JSON.stringify({type: def.id, data: vals()})
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'ثبت درخواست انجام نشد. دوباره تلاش کنید.');
      showDone();
    } catch (error) {
      let note = form.querySelector('.server-error');
      if (!note) { note = document.createElement('p'); note.className = 'err server-error'; note.setAttribute('role', 'alert'); form.prepend(note); }
      note.textContent = error.message || 'ارتباط با سرور برقرار نشد؛ لطفاً دوباره تلاش کنید.';
    }
  });
  done.addEventListener('click', e => {
    const b = e.target.closest('[data-act]'); if(!b) return;
    if(b.dataset.act === 'edit'){ done.hidden = true; form.hidden = false; return; }
    const text = $('.msg', done).textContent, label = $('span', b);
    const fallback = () => { const r = document.createRange(); r.selectNodeContents($('.msg', done)); const s = getSelection(); s.removeAllRanges(); s.addRange(r); label.textContent = 'متن را انتخاب و کپی کنید'; };
    try { navigator.clipboard.writeText(text).then(() => { label.textContent = 'کپی شد'; setTimeout(() => { label.textContent = 'کپی متن'; }, 2000); }, fallback); } catch(_) { fallback(); }
  });
  return {
    set(n, v){ const e = el(n); if(e){ e.value = v; e.dispatchEvent(new Event('change', {bubbles: true})); } },
    reset(){ done.hidden = true; form.hidden = false; }
  };
}

