/* ---------- ناوبری ---------- */
const ROUTES = ['home', 'classes', 'coach', 'plans', 'blog', 'contact'];
let pending = null;

function selectTab(name){
  ['training', 'nutrition', 'assessment'].forEach(n => {
    const on = n === name;
    const t = $('#t-' + n); t.setAttribute('aria-selected', on); t.tabIndex = on ? 0 : -1;
    $('#p-' + n).hidden = !on;
  });
}
function setGroup(g, s){
  forms.reg.reset();
  forms.reg.set('group', g);
  if(s) forms.reg.set('session', s);
}
function scrollToId(id){ const e = $('#' + id); if(e) e.scrollIntoView({behavior: reduce ? 'auto' : 'smooth', block: 'start'}); }

function render(){
  const h = (location.hash || '#home').slice(1);
  const r = ROUTES.indexOf(h) > -1 ? h : 'home';
  ROUTES.forEach(x => { $('#v-' + x).hidden = x !== r; });
  $$('.nav a, .drawer a.dl').forEach(a => { if(a.dataset.go === r) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current'); });
  $('#drawer').hidden = true; $('#burger').setAttribute('aria-expanded', 'false');
  const d = pending; pending = null;
  if(d && d.tab) selectTab(d.tab);
  if(d && d.group) setGroup(d.group, d.session);
  if(d && d.scroll) requestAnimationFrame(() => scrollToId(d.scroll)); else scrollTo(0, 0);
}
function go(name, d){
  pending = d || null;
  if((location.hash || '#home') === '#' + name) render(); else location.hash = name;
}

document.addEventListener('click', e => {
  const a = e.target.closest('[data-go]');
  if(a){ e.preventDefault(); go(a.dataset.go, {tab: a.dataset.tab, group: a.dataset.group, session: a.dataset.session, scroll: a.dataset.scroll}); return; }
  const p = e.target.closest('[data-pick]');
  if(p){ setGroup(p.dataset.pick, p.dataset.session); scrollToId('register'); return; }
  const c = e.target.closest('[data-copy-addr]');
  if(c){
    const label = $('span', c);
    const ok = () => { label.textContent = 'کپی شد'; setTimeout(() => { label.textContent = 'کپی آدرس'; }, 2000); };
    try { navigator.clipboard.writeText(ADDRESS).then(ok, () => { label.textContent = 'آدرس را انتخاب کنید'; }); } catch(_) { label.textContent = 'آدرس را انتخاب کنید'; }
  }
});
addEventListener('hashchange', render);

/* تب‌ها */
$$('.tabs [role=tab]').forEach(t => {
  t.addEventListener('click', () => selectTab(t.id.slice(2)));
  t.addEventListener('keydown', e => {
    const ids = ['training', 'nutrition', 'assessment'], i = ids.indexOf(t.id.slice(2));
    if(e.key === 'ArrowLeft' || e.key === 'ArrowRight'){
      const n = ids[(i + (e.key === 'ArrowLeft' ? 1 : ids.length - 1)) % ids.length];
      selectTab(n); $('#t-' + n).focus();
    }
  });
});

/* منوی موبایل و پوسته */
$('#burger').addEventListener('click', () => {
  const d = $('#drawer'); d.hidden = !d.hidden;
  $('#burger').setAttribute('aria-expanded', String(!d.hidden));
});
function themeIcon(){
  const dark = document.documentElement.dataset.theme === 'dark' || (!document.documentElement.dataset.theme && matchMedia('(prefers-color-scheme: dark)').matches);
  $('#theme').innerHTML = ico(dark ? 'sun' : 'moon', 20);
  $('#theme').dataset.dark = dark;
}
$('#theme').addEventListener('click', () => {
  const next = $('#theme').dataset.dark === 'true' ? 'light' : 'dark';
  document.documentElement.dataset.theme = next;
  try { localStorage.setItem('aliupfit-theme', next); } catch(_) {}
  themeIcon();
});
try { const t = localStorage.getItem('aliupfit-theme'); if(t) document.documentElement.dataset.theme = t; } catch(_) {}
themeIcon();

/* ---------- ساخت محتوا ---------- */
$$('[data-cap]').forEach(e => { e.innerHTML = capHTML(e.dataset.cap); });
$$('[data-place]').forEach(e => { e.innerHTML = placeHTML(); });
$$('[data-price]').forEach(e => {
  const p = CONFIG.prices[e.dataset.price];
  e.innerHTML = ico('clipboard', 24) + '<span>' + (p ? 'هزینه: ' + p : 'هزینه پس از بررسی اطلاعات اعلام می‌شود') + '<small>پرداخت آنلاین در نسخه‌های بعد اضافه می‌شود</small></span>';
});
$('#contact-list').innerHTML = contactHTML();
forms.reg = makeForm($('#form-reg'), FORMS.reg);
forms.training = makeForm($('#form-training'), FORMS.training);
forms.nutrition = makeForm($('#form-nutrition'), FORMS.nutrition);
forms.assessment = makeForm($('#form-assessment'), FORMS.assessment);
forms.contact = makeForm($('#form-contact'), FORMS.contact);
const coachPortrait = CONFIG.coachPhoto || PHOTOS.coach;
if(coachPortrait){ $('#portrait').insertAdjacentHTML('afterbegin', '<img alt="علی فهیمی، مربی ورزش کودکان" src="' + coachPortrait + '">'); }
/* عکس‌ها، قیمت‌ها و نوار مهارت‌ها */
$$('[data-photo]').forEach(im => { im.src = PHOTOS[im.dataset.photo]; });
$$('[data-prices]').forEach(ul => { ul.innerHTML = PACKS[ul.dataset.prices].map(p => '<li><span>' + p.label + '</span><b>' + money(p.u) + '</b></li>').join(''); });
$$('[data-ptag]').forEach(e => {
  const k = e.dataset.ptag;
  e.textContent = k === 'g612' ? 'از ' + money(8) : k === 'g35' ? '۸ جلسه · ' + money(6) : money(2);
});
const WORDS = ['تعادل', 'هماهنگی', 'چابکی', 'قدرت', 'استقامت', 'اعتمادبه‌نفس', 'بازی', 'رشد'];
const strip = WORDS.map(w => '<span>' + w + '</span><i class="star"></i>').join('');
$('#strip').innerHTML = strip + strip;

/* تایپ شدن عنوان‌ها */
function typeIt(el){
  const full = el.dataset.full;
  el.style.minHeight = el.offsetHeight + 'px';
  el.classList.remove('tw-wait'); el.classList.add('tw-caret');
  el.textContent = '';
  let i = 0;
  (function step(){
    i += 1; el.textContent = full.slice(0, i);
    if(i < full.length) setTimeout(step, 26);
    else { el.classList.remove('tw-caret'); el.style.minHeight = ''; }
  })();
}
const tw = $$('[data-type]');
tw.forEach(el => { el.dataset.full = el.textContent.trim(); });
if(!reduce && 'IntersectionObserver' in window){
  const io = new IntersectionObserver(es => es.forEach(e => { if(e.isIntersecting){ io.unobserve(e.target); typeIt(e.target); } }), {threshold: .6});
  tw.forEach(el => { el.classList.add('tw-wait'); io.observe(el); });
}

// ورود نرم عناصر در زمان اسکرول، با رعایت تنظیم کاهش حرکت سیستم
if(!reduce && 'IntersectionObserver' in window){
  const revealTargets = $$('.svc,.group,.topic,.why-item,.crow,.slot,.article,.place,.banner,.collage .ph,.vibe,.cta-band');
  const revealIO = new IntersectionObserver(entries => entries.forEach(entry => {
    if(entry.isIntersecting){ entry.target.classList.add('is-visible'); revealIO.unobserve(entry.target); }
  }), {threshold:.12,rootMargin:'0px 0px -24px 0px'});
  revealTargets.forEach((el,i) => { el.classList.add('reveal'); el.style.setProperty('--reveal-delay', (i%5)*65+'ms'); revealIO.observe(el); });
}
hydrateIcons(document);
render();
})();
</script>

</body>
</html>
